{
  "name": "@lidtop/opencode-media",
  "version": "0.2.0",
  "description": "OpenCode agent tools that generate speech, sound, and images with your OpenRouter key",
  "license": "MIT",
  "author": "ZackarySantana",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ZackarySantana/opcode.git",
    "directory": "plugins/media"
  },
  "keywords": [
    "opencode",
    "opencode-plugin"
  ],
  "engines": {
    "opencode": "^2.2.0"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/types/plugins/media/src/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/types/plugins/media/src/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "dependencies": {
    "@opencode/plugin": "2.2.0"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  }
